llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "In humans, free baicalein has low oral bioavailability that limits clinical use; this high-transfer human result supports a low F prediction for the query, which shares multiple phenolic groups and poor-permeability characteristics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Chrysin in healthy volunteers has an estimated oral bioavailability of 0.003–0.02% after a 400 mg oral dose, with most of the dose recovered in feces; this is direct human evidence of F far below 20% and supports low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Rebamipide, a carboxylic-acid-containing drug, has under 10% oral bioavailability in humans; the query also contains an ionizable carboxylic acid and phenolic groups, so this high-transfer analogue supports a low F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Defibrotide absolute oral bioavailability in patients was 2.6–13%, below the 20% threshold; despite being a different chemical class, the high transfer score makes this human quantitative evidence supportive of low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Aniracetam is very rapidly absorbed but widely metabolized, resulting in extremely low oral bioavailability in humans; this demonstrates that high-transfer human low-F outcomes can arise from metabolic/clearance liabilities relevant to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer human evidence points to low oral bioavailability, with quantitative values well below 20%. The query's ionized carboxylic acid, phenolic groups, and moderate polarity are consistent with poor permeability and extensive metabolism. The physicochemical prior is mixed, but the transferable experimental evidence strongly supports a low F prediction.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "No specific data on intestinal permeability, efflux transport, or metabolic stability of the query.",
    "No formulation or dose-ranging data for the query; oral bioavailability can be formulation-sensitive.",
    "All evidence is from analogues, although transfer scores are high."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C13", "C08", "C06", "C11", "C01", "C14", "C05", "C09", "C15", "C04", "C17", "C10", "C03", "C16", "C12", "C02", "C07"],
      "decision_effect": "changed",
      "direction": "supportive",
      "family": "human low oral bioavailability evidence"
    }
  ],
  "revision_action": "initial"
}

